import json
b = json.load(open('pairs_before.json')); a = json.load(open('pairs_after.json'))
for i,(r0,r1) in enumerate(zip(b,a)):
    if r0 != r1 and r0['transactionCategory']=='REVERSAL':
        print(f"idx {i}")
        for j in range(i-2, i+1):
            print("   ", j, b[j]['type'], b[j]['description'], b[j]['amount'])
        break
EOF

cd /app/categorizationapp/categorizationapp && grep -rn "shift(periods=2)\|shift(periods=-" --include=*.py . ; echo "--- multi-group patterns with index=0:"; python - <<'EOF'
import re, pathlib, sys
sys.path.insert(0, '.')
import warnings; warnings.filterwarnings('ignore')
# resolve constants
import importlib
consts = {}
for mod in ("UtilityScripts.RegexConstants", "UtilityScripts.BankRegexConstants"):
    pass
for p in pathlib.Path('.').rglob('*.py'):
    txt = p.read_text()
    for m in re.finditer(r'py_extract\(([^\n]*?)index=(\d+)\)', txt):
        call, idx = m.group(1), int(m.group(2))
        pm = re.search(r'pat=("(?:[^"\\]|\\.)*"|[A-Z_0-9]+)', call)
        if not pm: continue
        pat = pm.group(1)
        if pat.startswith('"'):
            raw = pat[1:-1].replace('\\\\','\\')
            ngroups = len(re.findall(r'(?<!\\)\((?!\?)', raw))
            if ngroups > 1:
                line = txt[:m.start()].count('\n')+1
                print(f"{p}:{line} groups={ngroups} index={idx} pat={raw}")
EOF

